package net.officefloor.hq.app.holiday;

import java.sql.Date;
import java.time.LocalDate;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The holidays on each sheet. */
@Repository
public class Holidays {

    private final JdbcTemplate jdbc;

    public Holidays(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every holiday on the sheet (yyyy-MM-dd), earliest first. */
    public List<String> list(String sheet) {
        return jdbc.query("SELECT holiday_on FROM holiday WHERE sheet = ? ORDER BY holiday_on",
                (rs, i) -> rs.getDate("holiday_on").toLocalDate().toString(), sheet);
    }

    /** Whether the date is already on the sheet's list. */
    public boolean has(String sheet, LocalDate date) {
        Integer found = jdbc.queryForObject("SELECT COUNT(*) FROM holiday WHERE sheet = ? AND holiday_on = ?", Integer.class,
                sheet, Date.valueOf(date));
        return found != null && found > 0;
    }

    public void add(String sheet, LocalDate date) {
        jdbc.update("INSERT INTO holiday (sheet, holiday_on) VALUES (?, ?)", sheet, Date.valueOf(date));
    }

    /** The date itself when it is not a holiday on the sheet, else the next day that is not one. */
    public LocalDate past(String sheet, LocalDate date) {
        Set<LocalDate> days = new HashSet<>(jdbc.query("SELECT holiday_on FROM holiday WHERE sheet = ? AND holiday_on >= ?",
                (rs, i) -> rs.getDate("holiday_on").toLocalDate(), sheet, Date.valueOf(date)));
        LocalDate on = date;
        while (days.contains(on)) {
            on = on.plusDays(1);
        }
        return on;
    }
}
    public boolean figureApartFrom(Claim claim, LocalDate today, List<Rate> rates, Dated floor) {
        String then = gradeOn(claim.date());
        return claim.fixed()
                || (then != null && !then.equals(gradeOn(today)) && claim.figure(rates, then, floor) != null)
                || (then != null && !LocalDate.parse(claim.date()).isAfter(today)
                        && claim.figure(rates, then, floor) != null);
    }

    /**
     * The due-by of a claim of theirs dated {@code date}, fixed when it is made: the date plus the first of their own
     * terms, the terms of their grade then, and the sheet's terms then; moved past the sheet's holidays (as they stand
     * now) to the next day that is not one.
     */
    public LocalDate dueBy(String sheet, LocalDate date, Settings settings, Holidays holidays) {
        return holidays.past(sheet, date.plusDays(terms != null ? terms : settings.terms(sheet, gradeOn(date), date)));
    }

    /** The grade in force on the claim's date (yyyy-mm-dd). */
    public String gradeOn(String date) {
        return gradeOn(LocalDate.parse(date));
    }
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        if (name.isBlank()) {
            throw new InvalidPersonException("A name is required");
        }
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be a number of 0.00 or more with up to two decimals");
        }
        ClaimInput input = new ClaimInput(new BigDecimal(amount), settings.entryDay(sheet), "");
        // The due-by it would be fixed with: from the person of the name, else from a new person of grade A.
        Person person = people.findByName(sheet, name);
        LocalDate dueBy = person != null ? person.dueBy(sheet, input.date(), settings, holidays)
                : holidays.past(sheet, input.date().plusDays(settings.terms(sheet, "A", input.date())));
        if (periods.closedOn(sheet, dueBy)) {
            throw new InvalidClaimException("A claim may not be due inside a closed period");
        }
        body.set(new QuickAddRequest(name, amount));
        claim.set(input);
    }
}
